Problem:
A coconut seller has to transport coconuts using either rickshaws or ox carts. The rickshaws can take 50 coconuts each and cost $10 per trip. The ox carts can take 30 coconuts each and cost $8 per trip. The seller has at most $200 to spend on transporting the coconuts. Due to pollution, the number of rickshaws must not exceed the number of ox carts. Formulate a LP to maximize the number of coconuts that can be transported.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "rickshaw trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "ox cart trips",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "rickshaw trips",
     "coef": 50.0
    },
    {
     "var": "ox cart trips",
     "coef": 30.0
    }
   ]
  },
  "constraints": [
   {
    "name": "budget",
    "terms": [
     {
      "var": "rickshaw trips",
      "coef": 10.0
     },
     {
      "var": "ox cart trips",
      "coef": 8.0
     }
    ],
    "sense": "<=",
    "rhs": 200.0
   },
   {
    "name": "pollution",
    "terms": [
     {
      "var": "rickshaw trips",
      "coef": 1.0
     },
     {
      "var": "ox cart trips",
      "coef": -1.0
     }
    ],
    "sense": "<=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 880.0,
  "values": {
   "rickshaw trips": 11.0,
   "ox cart trips": 11.0
  },
  "binding": [
   "pollution"
  ],
  "slack": {
   "budget": 2.0,
   "pollution": 0.0
  },
  "shadow_prices": null
 }
}
